  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 1, $j$1.1 Colonial Voices and the Plain Style$j$, $j${"readings": [{"title": "Micah 6 (King James Version)", "url": "/portal/bible/Micah/6"}], "body": "American literature begins with people who wrote to record, to persuade and to worship. The first colonial writers were settlers, ministers and governors. William Bradford wrote a history of the Plymouth settlement. Anne Bradstreet wrote poems about family and faith. Jonathan Edwards preached powerful sermons in the 1700s. Many of these writers used the plain style: clear, direct words, short sentences and images drawn from daily life and from Scripture.\n\nTo read informational and historical writing well, find the main idea (what the whole passage is mostly about) and the supporting details that prove it. Notice how the text is organized: chronological order (events in time order), cause and effect, comparison, or problem and solution. Notice text features such as titles, dates and scripture references.\n\nRead this original passage in the plain style:\n\nWe came to this shore with little, and we had less before the winter was done. The ground was hard, the corn was thin, and the sea behind us offered no road home. Yet we kept the Lord's day, and we shared what we had, for a neighbor's hunger is a debt that each of us owes.\n\nMain idea: hardship was met with faith and sharing. Organization: a problem (hardship) followed by a response (faith and generosity). Plain style clues: short sentences, concrete nouns (ground, corn, sea) and a moral lesson at the end.\n\nYour task: (1) State the main idea of the passage in your own words. (2) Name two supporting details. (3) Identify how the passage is organized and give one feature of the plain style.\n\nFlorida standards: ELA.11.R.2.1, ELA.11.R.2.2, ELA.K12.EE.1.1.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.2.1, ELA.11.R.2.2, ELA.K12.EE.1.1", "script": "Welcome to English 3. I am Dr. Alex L. Jenkins Sr., and I am glad you are here. This year we walk through the story of America by reading the voices that built it. Listen, a nation is not only built with stone and steel. It is built with words.\n\nOur first voices are the colonial writers. William Bradford wrote a history of the Plymouth settlement. Anne Bradstreet wrote poems about her family and her faith. Jonathan Edwards preached sermons in the 1700s that people remembered for years. These writers loved the plain style. That means clear, direct words, short sentences, and pictures taken from daily life and from the Bible.\n\nNow watch this. When we read history or informational writing, we hunt for two things. First, the main idea. That is what the whole passage is mostly about. Second, the supporting details. Those are the facts, examples and images that prove the main idea. Then we ask how the writer organized the piece. Is it in time order? Is it cause and effect? Is it comparison? Or is it a problem followed by a solution?\n\nLet us read an original passage in the plain style. We came to this shore with little, and we had less before the winter was done. The ground was hard, the corn was thin, and the sea behind us offered no road home. Yet we kept the Lord's day, and we shared what we had, for a neighbor's hunger is a debt that each of us owes.\n\nWhat is the main idea? Hardship was met with faith and sharing. What are the supporting details? The hard ground, the thin corn, the sea with no road home, keeping the Lord's day, and sharing what they had. How is it organized? A problem, which is the hardship, followed by a response, which is faith and generosity. And look at the plain style. Short sentences. Concrete words like ground, corn and sea. And a lesson at the end about owing a debt to a hungry neighbor.\n\nYour task today. State the main idea in your own words. Name two supporting details. And tell how the passage is organized and name one plain style feature. Take the four question check when you finish.\n\nPlain words, spoken in truth, can carry a whole people through a winter. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.1 Colonial Voices and the Plain Style$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 2, $j$1.2 Benjamin Franklin and the Self Made American$j$, $j${"readings": [{"title": "Proverbs 6 (King James Version)", "url": "/portal/bible/Proverbs/6"}], "body": "Benjamin Franklin (1706 to 1790) was a printer, scientist, writer and statesman. In Poor Richard's Almanack, which he published beginning in 1732, he gathered short sayings called maxims. In his Autobiography he told the story of how he improved himself. He also described a plan to practice thirteen virtues, including temperance, order, industry, sincerity, justice and humility.\n\nFranklin's purpose was both practical and moral: to help ordinary people work hard, save wisely and become people of character. He used humor, short sentences and everyday pictures to make advice easy to remember.\n\nTo find an author's main ideas, ask: What does the writer want me to believe or do? Which details repeat? What is the lesson? To explain how an author pursues a goal, look at the choices: tone, examples, structure and word choice.\n\nRead these original maxims in Franklin's spirit:\n\nA coin kept is a seed planted. The lamp that is trimmed at night is bright in the morning. Who borrows for pride will pay for it twice.\n\nMain idea: careful habits today bring benefits later. Method: short sentences, pictures from daily life (seed, lamp) and a warning.\n\nCompare with Scripture: Proverbs 6:6 invites us to consider the ant and be wise. Franklin and the Bible both teach by memorable pictures.\n\nYour task: (1) State the main idea of the three maxims. (2) Explain how the author uses a picture (seed or lamp) to make the idea memorable. (3) Write one original maxim of your own about work or character.\n\nFlorida standards: ELA.11.R.2.2, ELA.11.R.2.3.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.2.2, ELA.11.R.2.3", "script": "Now we meet one of the most famous writers in early America, Benjamin Franklin. He lived from seventeen hundred six to seventeen hundred ninety. He was a printer, a scientist, a writer and a statesman. And he was a great teacher of ordinary people.\n\nBeginning in seventeen thirty two, Franklin published Poor Richard's Almanack. It was full of maxims. A maxim is a short saying that carries a lesson. In his Autobiography he told how he worked to improve himself. He even made a plan to practice thirteen virtues. Temperance, order, industry, sincerity, justice, humility, and others.\n\nWatch this. Why did he write this way? His purpose was practical and moral. He wanted to help ordinary people work hard, save wisely and grow in character. And he made the advice easy to remember with humor, short sentences and pictures from everyday life.\n\nHow do we find an author's main ideas? Ask three questions. What does the writer want me to believe or do? Which details repeat? And what is the lesson? Then ask how the author accomplishes the goal. Look at tone, examples, structure and word choice.\n\nLet us try with three original maxims in Franklin's spirit. A coin kept is a seed planted. The lamp that is trimmed at night is bright in the morning. Who borrows for pride will pay for it twice. The main idea is that careful habits today bring benefits later. And see the method. Short sentences. Pictures from daily life, a seed and a lamp. And a warning about pride.\n\nThe Bible teaches the same way. Proverbs chapter six invites us to consider the ant and be wise. The writer of Proverbs and Franklin both teach with memorable pictures.\n\nYour task today. State the main idea of the three maxims. Explain how the picture of a seed or a lamp makes the idea memorable. And write one maxim of your own about work or character. Take the four question check when you finish.\n\nA small habit, kept faithfully, builds a great life. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.2 Benjamin Franklin and the Self Made American$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 3, $j$1.3 Revolutionary Rhetoric: Speeches That Stirred a Nation$j$, $j${"readings": [{"title": "Nehemiah 4 (King James Version)", "url": "/portal/bible/Nehemiah/4"}], "body": "In the years before 1776, speakers and writers used rhetoric, the art of persuasion, to move the colonies toward independence. Patrick Henry spoke to the Virginia Convention in March 1775 and ended with the famous words Give me liberty or give me death. Thomas Paine wrote The American Crisis in 1776 and began with the words These are the times that try men's souls.\n\nThe three classical appeals are:\nEthos: the speaker's credibility and character.\nPathos: an appeal to emotion.\nLogos: an appeal to logic, facts and reasons.\n\nRhetorical techniques include: rhetorical questions (questions asked for effect, not for an answer), repetition, parallelism (similar grammatical structure), strong contrast and vivid images.\n\nRead this original speech excerpt:\n\nShall we sit in silence while our neighbors are taxed and silenced? Shall we wait until the door is barred and the hour is past? I say no. Let us speak, let us stand, and let us be counted.\n\nAnalysis: Two rhetorical questions create urgency (pathos). Parallelism in Let us speak, let us stand, let us be counted builds rhythm and a call to action. The short answer I say no shows confidence (ethos). The mention of taxes gives a reason (logos).\n\nTo judge how effectively an author uses rhetoric, ask whether each technique supports the purpose and fits the audience.\n\nYour task: (1) Name two rhetorical techniques in the excerpt and quote each. (2) Identify one example of pathos, ethos or logos and explain it. (3) Decide whether the excerpt is effective for its audience and give a reason.\n\nFlorida standards: ELA.11.R.2.3, ELA.11.R.3.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.2.3, ELA.11.R.3.4", "script": "Listen, a speech can change history. In the years before seventeen seventy six, speakers and writers used rhetoric, which is the art of persuasion, to move the colonies toward independence. In March of seventeen seventy five, Patrick Henry spoke to the Virginia Convention and ended with the famous words, give me liberty or give me death. And in seventeen seventy six, Thomas Paine began The American Crisis with the words, these are the times that try men's souls.\n\nHow did they persuade? With three appeals. Ethos is the speaker's credibility and character. Why should we trust you? Pathos is an appeal to emotion. How do you want us to feel? And logos is an appeal to logic, facts and reasons. Does it make sense?\n\nNow watch this. Speakers also use techniques. A rhetorical question is a question asked for effect, not for an answer. Repetition says something again so the audience remembers. Parallelism uses similar grammar in a series, to build rhythm. Contrast sets two things side by side. And vivid images help the audience see the point.\n\nLet us study an original excerpt. Shall we sit in silence while our neighbors are taxed and silenced? Shall we wait until the door is barred and the hour is past? I say no. Let us speak, let us stand, and let us be counted.\n\nSee the two rhetorical questions. They create urgency, which is pathos. See the parallelism in let us speak, let us stand, let us be counted. It builds rhythm and a call to action. The short sentence, I say no, shows confidence, which is ethos. And the mention of taxes gives a reason, which is logos.\n\nTo judge whether a speech is effective, ask two questions. Does each technique support the purpose? And does it fit the audience?\n\nYour task today. Name two techniques and quote them. Identify one appeal and explain it. And decide whether the excerpt is effective for its audience. Take the four question check when you finish.\n\nUse your words the way a good builder uses stone, with purpose and care. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.3 Revolutionary Rhetoric: Speeches That Stirred a Nation$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'topic', 4, $j$1.4 The Declaration of Independence as an Argument$j$, $j${"readings": [{"title": "Galatians 5 (King James Version)", "url": "/portal/bible/Galatians/5"}], "body": "The Declaration of Independence was adopted on July 4, 1776. Thomas Jefferson was its main author. It is one of the most important arguments in American history.\n\nIts structure is clear and logical:\n1. Introduction: states the purpose, to explain to the world why the colonies are separating.\n2. Statement of principles: all people are created equal and have rights, including life, liberty and the pursuit of happiness. Governments exist to protect these rights.\n3. List of grievances: a long list of specific wrongs committed by the king.\n4. Statement of efforts: the colonists asked for help and were ignored.\n5. Conclusion: a declaration that the colonies are free and independent states.\n\nThis is a deductive argument: a general principle (people have rights), then evidence (the grievances), then a conclusion (separation is justified).\n\nThe writers appeal to a Creator, which gives their claim moral authority (ethos and pathos), and they list facts (logos).\n\nWhen you compare arguments on one topic, judge each for strength: Is the claim clear? Is the reasoning sound? Is the evidence relevant and enough? Do the authors use the same facts for different goals? A loyalist writer in 1776 could accept some of the same facts but argue that petitions and patience were better than separation.\n\nYour task: (1) Name the five parts of the Declaration in your own words. (2) Explain why the list of grievances is evidence. (3) Describe one way a loyalist might use the same facts for a different purpose.\n\nFlorida standards: ELA.11.R.2.1, ELA.11.R.2.3, ELA.11.R.2.4.", "video": "", "presenter": "Dr. Alex L. Jenkins Sr.", "standards": "ELA.11.R.2.1, ELA.11.R.2.3, ELA.11.R.2.4", "script": "Now we come to one of the most important arguments in all of history, the Declaration of Independence. It was adopted on July fourth, seventeen seventy six. Thomas Jefferson was the main author. And it is not only a famous document. It is a carefully built argument.\n\nListen to its structure, because the order matters. First, an introduction. It states the purpose, to explain to the world why the colonies are separating. Second, a statement of principles. All people are created equal, and they have rights, including life, liberty and the pursuit of happiness. Governments exist to protect these rights. Third, a list of grievances. That is a long list of specific wrongs committed by the king. Fourth, a statement of efforts. The colonists asked for help, and they were ignored. And fifth, a conclusion. The colonies declare themselves free and independent states.\n\nWatch this. This is a deductive argument. It starts with a general principle, which is that people have rights. Then it gives evidence, which is the list of grievances. And then it reaches a conclusion, which is that separation is justified. Principle, evidence, conclusion.\n\nNotice the appeals. The writers speak of a Creator, which gives their claim moral weight. That is ethos and pathos. And they list facts, which is logos.\n\nNow a skill for your toolbox. When you compare arguments on one topic, judge each one. Is the claim clear? Is the reasoning sound? Is the evidence relevant and enough? And do the authors use the same facts for different goals? A loyalist writer in seventeen seventy six might accept some of the same facts, but argue that petitions and patience were better than separation. Same facts, different purpose.\n\nYour task today. Name the five parts of the Declaration in your own words. Explain why the list of grievances counts as evidence. And describe one way a loyalist might use the same facts for a different purpose. Take the four question check when you finish.\n\nA just cause, plainly stated, is a strong foundation. Excellence, Faith, Purpose. I will see you in the next lesson."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'topic' and title = $j$1.4 The Declaration of Independence as an Argument$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'assessment', 1, $j$Assessment 1: Rhetorical Analysis Paragraph$j$, $j${"prompt": "Read this original speech excerpt and write a rhetorical analysis of at least 150 words.\n\nWe did not choose this storm, but we will choose how we stand in it. Our fathers cleared this ground with their hands. Our mothers taught us to pray before we could read. Shall we trade their courage for comfort? Shall we hide our children from the very truth that made us strong? I say no. We will work, we will learn, and we will rebuild, together.\n\nIn your analysis: (1) State the speaker's main idea and purpose. (2) Identify at least three rhetorical techniques or appeals (for example, rhetorical questions, parallelism, repetition, contrast, ethos, pathos or logos) and quote the words that show each one. (3) Judge how effective the excerpt would be for an audience of neighbors in a crisis and give two reasons. (4) Write in complete sentences with a clear topic sentence, evidence and a concluding sentence.", "rubric": "100 points. Main idea and purpose clearly stated: 20 points. Three techniques or appeals identified with quoted evidence: 30 points. Judgment of effectiveness with two reasons: 25 points. Organization, topic sentence and conclusion: 15 points. Grammar, spelling and complete sentences: 10 points. A score of 70 or above is passing."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'assessment' and title = $j$Assessment 1: Rhetorical Analysis Paragraph$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'discussion', 1, $j$Discussion 1: Words Fitly Spoken$j$, $j${"prompt": "Early American writers and speakers used words to teach, to comfort and to persuade. Write a post of at least 120 words that (1) explains in your own words what makes a speech or a piece of writing persuasive, (2) describes a time when words changed your mind or changed someone's life, (3) tells which voice from this unit, such as Bradstreet, Franklin, Henry, Paine or Jefferson, you found most interesting and why, and (4) connects your answer to Proverbs 25:11, which says, A word fitly spoken is like apples of gold in pictures of silver. Then write a respectful reply of at least 40 words to another student's post, or answer this question: Why does an author's purpose matter when we judge an argument? Keep your language clean and your tone kind."}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'discussion' and title = $j$Discussion 1: Words Fitly Spoken$j$);
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 1, $j$Check 1.1: Colonial Voices and the Plain Style$j$, $j${"questions": [{"q": "The main idea of a passage is:", "options": ["The first sentence only", "The title only", "The longest detail", "What the whole passage is mostly about"]}, {"q": "The plain style uses:", "options": ["Secret symbols only", "Clear, direct words and short sentences", "Words nobody can understand", "Long, decorated sentences"]}, {"q": "A passage that describes a hardship and then the way people respond is organized as:", "options": ["Definition only", "Problem and solution", "Comparison", "Chronological list of dates"]}, {"q": "Which writer wrote poems about family and faith in colonial America?", "options": ["Mark Twain", "Edgar Allan Poe", "Ernest Hemingway", "Anne Bradstreet"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Colonial Voices and the Plain Style$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,1,1,3}'::int[], array[$j$The main idea is the central point of the entire passage.$j$,$j$The plain style is direct and clear.$j$,$j$A hardship followed by a response is problem and solution.$j$,$j$Anne Bradstreet was a colonial poet.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.1: Colonial Voices and the Plain Style$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 2, $j$Check 1.2: Benjamin Franklin and the Self Made American$j$, $j${"questions": [{"q": "A maxim is:", "options": ["A list of dates", "A type of speech about war", "A long poem", "A short saying that carries a lesson"]}, {"q": "Franklin published Poor Richard's Almanack to:", "options": ["Report weather forecasts only", "Entertain only with no lesson", "Teach practical and moral lessons in memorable ways", "Argue for a king"]}, {"q": "In the maxim A coin kept is a seed planted, the seed is a picture of:", "options": ["Sadness", "A dangerous plant", "Growth that comes from saving", "A garden tool"]}, {"q": "To find an author's main idea you should ask:", "options": ["Which word is the longest?", "How long is the title?", "What is the page number?", "What does the writer want me to believe or do?"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Benjamin Franklin and the Self Made American$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{3,2,2,3}'::int[], array[$j$A maxim is a brief saying that teaches a lesson.$j$,$j$Franklin's purpose was both practical and moral.$j$,$j$The seed pictures saving that grows over time.$j$,$j$Look for the belief or action the writer is urging.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.2: Benjamin Franklin and the Self Made American$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 3, $j$Check 1.3: Revolutionary Rhetoric: Speeches That Stirred a Nation$j$, $j${"questions": [{"q": "An appeal to the speaker's credibility and character is called:", "options": ["Logos", "Ethos", "Pathos", "Irony"]}, {"q": "A question asked for effect, not for an answer, is a:", "options": ["Quiz question", "Rhetorical question", "Factual question", "Summary"]}, {"q": "Similar grammatical structure repeated in a series is called:", "options": ["Setting", "Parallelism", "Flashback", "Allegory"]}, {"q": "Which writer began The American Crisis with the words These are the times that try men's souls?", "options": ["Benjamin Franklin", "Anne Bradstreet", "Patrick Henry", "Thomas Paine"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Revolutionary Rhetoric: Speeches That Stirred a Nation$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{1,1,1,3}'::int[], array[$j$Ethos builds trust in the speaker.$j$,$j$Rhetorical questions create impact without needing an answer.$j$,$j$Parallelism repeats grammar to build rhythm.$j$,$j$Thomas Paine wrote The American Crisis.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.3: Revolutionary Rhetoric: Speeches That Stirred a Nation$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 4, $j$Check 1.4: The Declaration of Independence as an Argument$j$, $j${"questions": [{"q": "The Declaration of Independence was adopted on:", "options": ["July 4, 1776", "April 19, 1775", "July 4, 1876", "September 17, 1787"]}, {"q": "Who was the main author of the Declaration of Independence?", "options": ["Patrick Henry", "Thomas Paine", "Thomas Jefferson", "Benjamin Franklin"]}, {"q": "The list of grievances in the Declaration serves as:", "options": ["A conclusion only", "A title page", "Evidence for the argument", "A poem"]}, {"q": "An argument that begins with a general principle, gives evidence and reaches a conclusion is:", "options": ["A haiku", "A flashback", "Accidental", "Deductive"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: The Declaration of Independence as an Argument$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,2,3}'::int[], array[$j$The Declaration was adopted on July 4, 1776.$j$,$j$Thomas Jefferson was its main author.$j$,$j$The grievances are the evidence that supports the claim.$j$,$j$That order is deductive reasoning.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Check 1.4: The Declaration of Independence as an Argument$j$ on conflict (item_id) do nothing;
  insert into public.course_items (course_id, kind, position, title, content) select cid, 'quiz', 5, $j$Unit Quiz 1: Early American Voices and Rhetoric$j$, $j${"questions": [{"q": "The plain style is best described as:", "options": ["Clear, direct words and short sentences", "Poetry only", "Secret code", "Long, decorated sentences"]}, {"q": "The main idea of a passage is:", "options": ["The date", "The longest sentence", "What the whole passage is mostly about", "The author's name"]}, {"q": "A maxim is:", "options": ["A list of names", "A short saying that carries a lesson", "A long speech", "A type of battle"]}, {"q": "Ethos is an appeal to:", "options": ["Logic and facts", "The speaker's credibility and character", "Emotion", "Humor"]}, {"q": "Pathos is an appeal to:", "options": ["Logic and facts", "The speaker's credibility", "Grammar", "Emotion"]}, {"q": "Logos is an appeal to:", "options": ["Humor only", "Emotion only", "Fear only", "Logic, facts and reasons"]}, {"q": "Which sequence best describes the structure of the Declaration of Independence?", "options": ["Date, price, address", "Principles, grievances, conclusion", "Conclusion, jokes, title", "Story, riddle, song"]}, {"q": "When two authors use the same facts for different purposes, a good reader should:", "options": ["Pick the one with the most adjectives", "Judge the reasoning and evidence of each", "Choose the longer one", "Ignore both"]}]}$j$::jsonb where not exists (select 1 from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Early American Voices and Rhetoric$j$);
  insert into public.quiz_keys (item_id, answers, explains) select id, '{0,2,1,1,3,3,1,1}'::int[], array[$j$The plain style is direct and clear.$j$,$j$The main idea is the central point.$j$,$j$A maxim is a brief, memorable lesson.$j$,$j$Ethos builds trust in the speaker.$j$,$j$Pathos stirs feeling.$j$,$j$Logos uses reason and evidence.$j$,$j$It states principles, lists grievances and reaches a conclusion.$j$,$j$Compare the strength of each argument.$j$] from public.course_items where course_id = cid and kind = 'quiz' and title = $j$Unit Quiz 1: Early American Voices and Rhetoric$j$ on conflict (item_id) do nothing;
